  "description": "Illustrates the significance of point density in archaeological point clouds for information richness.",
  "definition": "Measured as points per square meter. Values around 100 capture basic site topography, 1,000 can document structural details, while 10,000+ enables analysis of surface textures and fine engravings across multiple scales of inquiry."
}

{
  "id": 23,
  "knowledge": "Coverage Percentage",
  "description": "Illustrates the significance of coverage percentage in archaeological scans for site completeness assessment.",
  "definition": "Percentage of target area successfully captured in scan data. Values above 95% indicate near-complete documentation, while 80% might have significant gaps requiring additional scanning or interpolation methods for comprehensive site analysis."
}

{
  "id": 0,
  "knowledge": "Scan Resolution Index (SRI)",
  "description": "A sophisticated compound index measuring the overall resolution quality of a scan based on resolution and point density.",
  "definition": "SRI = \\frac{\\log_{10}(\\text{Scan Resolution (mm)} \\times 10^3)}{\\log_{10}(\\text{Point Density (points/m\u00b2)})} \\times 5, \\text{ where lower values indicate higher quality resolution and more balanced scanning parameters.}"
}

{
  "id": 1,
  "knowledge": "Scan Coverage Effectiveness (SCE)",
  "description": "Measures how effectively a scan covers its target area considering both coverage percentage and overlap redundancy.",
  "definition": "SCE = \\text{Coverage (%)} \\times \\left(1 + \\frac{\\text{Overlap (%)}}{100} \\times \\left(1 - \\frac{\\text{Coverage (%)}}{100}\\right)\\right), \\text{ where higher values indicate more effective coverage with appropriate overlap.}"
}

{
  "id": 2,
  "knowledge": "Point Cloud Density Ratio (PCDR)",
  "description": "Evaluates the relationship between total points and cloud density, used to assess scan efficiency and data distribution.",
  "definition": "PCDR = \\frac{\\text{Total Points}}{\\text{Point-Cloud Density Code} \\times \\text{Surface Area (m\u00b2)}}, \\text{ where higher values suggest more efficient and spatially consistent scanning techniques.}"
}

