args.sql:
SELECT COUNT(*) FROM (
    SELECT DISTINCT ON (s.questregistry) s.questregistry AS scan_id
    FROM scans s
    LEFT JOIN pointcloud pc ON s.arcref = pc.arcref
    ORDER BY s.questregistry
) sub;
